INSERT INTO mhr_records (
  machine_class, location, machine_name, currency_code, country_code, source_type, process_group,
  operators, setup_time_hr, direct_overhead_rate, indirect_overhead_rate, benchmark_direct_overhead_rate_usd_hr, benchmark_indirect_overhead_rate_usd_hr,
  total_machine_hour_rate, mhr_usd_per_hour, usd_labor_rate_per_hr, benchmark_labor_rate_usd_hr, usd_lhr_total,
  work_center_labor_rate_factor, labor_time_standard, wage_grade, avg_utilization, good_part_yield, manufacturer_country, specs, benchmark_source_key
)
SELECT v.machine_class, v.location, v.machine_name, v.currency_code, v.country_code, v.source_type, v.process_group,
  v.operators::numeric, v.setup_time_hr::numeric, v.rate::numeric, v.rate::numeric, v.rate::numeric, v.rate::numeric,
  v.rate::numeric, v.rate::numeric, v.labour::numeric, v.labour::numeric, v.labour::numeric,
  v.wclrf::numeric, v.lts::numeric, v.wage_grade, v.util::numeric, v.yield::numeric, v.manufacturer_country, v.specs::jsonb, v.source_key
FROM (VALUES
  ($str$stock_machining_material_stock$str$, $str$USA$str$, $str$Default Material Stock$str$, $str$USD$str$, $str$US$str$, $str$BENCHMARK$str$, $str$Stock Machining$str$, 0, 0, 0, 0, 1, 0, $str$0 - Metal$str$, 0.78, 1, $str$USA$str$, $jsonb${"source":"memory/Stock Maching/Machine/machines_material_stock.csv","standard_stock_length_mm":6096,"is_preferred":true,"overhead_multiplier":0,"data_source":"eMithran Baseline","rate_basis":"memory/Stock Maching/Machine/machines_material_stock.csv: the stock as supplied, no rate"}$jsonb$::jsonb, $str$Material Stock:Default Material Stock$str$),
  ($str$stock_machining_material_stock$str$, $str$India$str$, $str$Default Material Stock$str$, $str$USD$str$, $str$IN$str$, $str$BENCHMARK$str$, $str$Stock Machining$str$, 0, 0, 0, 0, 1, 0, $str$0 - Metal$str$, 0.78, 1, $str$USA$str$, $jsonb${"source":"memory/Stock Maching/Machine/machines_material_stock.csv","standard_stock_length_mm":6096,"is_preferred":true,"overhead_multiplier":0,"data_source":"eMithran Baseline","rate_basis":"memory/Countries data/India_XML_Data_.csv: the stock as supplied, no rate"}$jsonb$::jsonb, $str$Material Stock:Default Material Stock:India$str$)
) AS v(machine_class, location, machine_name, currency_code, country_code, source_type, process_group, operators, setup_time_hr, rate, labour,
  wclrf, lts, wage_grade, util, yield, manufacturer_country, specs, source_key)
WHERE NOT EXISTS (
  SELECT 1 FROM mhr_records m WHERE m.machine_class = v.machine_class AND m.location = v.location AND lower(trim(m.machine_name)) = lower(trim(v.machine_name))
);

UPDATE process_taxonomy t SET machine_class = v.machine_class
FROM (VALUES ('Band Saw', $str$band_saw$str$), ('Material Stock', $str$stock_machining_material_stock$str$)) AS v(process_name, machine_class)
WHERE t.process_group = $str$Stock Machining$str$ AND t.process_name = v.process_name AND t.machine_class IS DISTINCT FROM v.machine_class;

INSERT INTO process_taxonomy (process_group, process_name, roadmap_status, is_active, display_order, notes)
SELECT $str$Stock Machining$str$, 'User-Defined Process', 'non_mfg', true, 1502,
  'A step the engineer adds to a Stock Machining part by hand: no machine and no wage grade of its own (memory/Stock Maching/processes.csv).'
WHERE NOT EXISTS (SELECT 1 FROM process_taxonomy WHERE process_group = $str$Stock Machining$str$ AND process_name = 'User-Defined Process');

DO $stock_machining_check$
DECLARE n integer; bad text[];
BEGIN
  SELECT count(*) INTO n FROM machining_reference_data WHERE source_version = $str$2026-Stock-Machining$str$ AND category = 'lookup_table'
    AND key IN ($str$tblPreferredSizes$str$, $str$tblPartingRingWidth$str$, $str$tblPartSpacing$str$, $str$validationDisplayControls$str$);
  IF n <> 4 THEN RAISE EXCEPTION 'Stock Machining: expected its 4 lookup tables staged, found %', n; END IF;
  SELECT jsonb_array_length(raw -> 'rows') INTO n FROM machining_reference_data
   WHERE source_version = $str$2026-Stock-Machining$str$ AND category = 'lookup_table' AND key = 'tblPreferredSizes';
  IF n < 814 THEN RAISE EXCEPTION 'Stock Machining: tblPreferredSizes holds % sizes, the whole table has 814', n; END IF;
  SELECT count(*) INTO n FROM machining_reference_data WHERE source_version = $str$2026-Stock-Machining$str$ AND category IN ('process', 'operation');
  IF n <> 6 THEN RAISE EXCEPTION 'Stock Machining: expected 3 processes and 3 operations staged, found %', n; END IF;
  SELECT count(*) INTO n FROM mhr_records WHERE process_group = $str$Stock Machining$str$ AND machine_class = $str$stock_machining_material_stock$str$ AND location IN ('USA', 'India');
  IF n <> 2 THEN RAISE EXCEPTION 'Stock Machining: expected Default Material Stock in USA and India, found % row(s)', n; END IF;
  -- A catalog row of the group without its machine class: its process would find no machine.
  SELECT array_agg(process_name ORDER BY process_name) INTO bad FROM process_taxonomy
   WHERE process_group = $str$Stock Machining$str$ AND process_name IN ('Band Saw', 'Material Stock') AND machine_class IS NULL;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'Stock Machining catalog rows without a machine class: %', bad; END IF;
  -- The saws themselves are migration 815's and the India twins': say what a process will find.
  SELECT count(*) INTO n FROM mhr_records WHERE machine_class = $str$band_saw$str$ AND location IN ('USA', 'India') AND COALESCE(mhr_usd_per_hour, 0) > 0;
  RAISE NOTICE 'Stock Machining: % rated band saws in USA and India (13 in each when migration 815 and the India twins are applied)', n;
END $stock_machining_check$;

NOTIFY pgrst, 'reload schema';
